import{_ as a,C as o,o as r,c as l,j as e,a as i,E as s,a6 as n}from"./chunks/framework.CnPv4DE1.js";const k=JSON.parse('{"title":"变现的3个阶段（为什么大多数创作者其实都很穷）","description":"","frontmatter":{"title":"变现的3个阶段（为什么大多数创作者其实都很穷）","originalTitle":"The 3 Stages Of Monetization (Why Most Creators Are Actually Broke)","date":"2024-06-15","originalUrl":"https://thedankoe.com/letters/the-3-stages-of-monetization-why-most-creators-are-actually-broke/","minutes":15,"sourceHash":"2b134543261e3c55597c6a6b69ef836e07f7ac2e4c91c205b4fe21384a8e1c18","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-3-stages-of-monetization-why-most-creators-are-actually-broke/"}]]},"headers":[],"relativePath":"letters/the-3-stages-of-monetization-why-most-creators-are-actually-broke.md","filePath":"letters/the-3-stages-of-monetization-why-most-creators-are-actually-broke.md"}'),c={name:"letters/the-3-stages-of-monetization-why-most-creators-are-actually-broke.md"};function h(m,p,g,u,d,f){const t=o("ArticleMeta");return r(),l("div",null,[p[0]||(p[0]=e("h1",{id:"变现的3个阶段-为什么大多数创作者其实都很穷",tabindex:"-1"},[i("变现的3个阶段（为什么大多数创作者其实都很穷） "),e("a",{class:"header-anchor",href:"#变现的3个阶段-为什么大多数创作者其实都很穷","aria-label":'Permalink to "变现的3个阶段（为什么大多数创作者其实都很穷）"'},"​")],-1)),s(t),p[1]||(p[1]=n('<p>我想成为一名创作者，因为我想做自己想做的事。</p><p>就这么简单。</p><p>这解释了为什么在哈里斯民意调查（Harris Poll）和晨间咨询（Morning Consult）的调查中，30%的美国儿童和54%的成年人表示他们想把成为创作者 / YouTuber作为职业。</p><p>大多数人会告诉他们“找份正经工作”或者“现实一点”，但我的看法恰恰相反。</p><p>我们都有一种天生的冲动，想去做一些能让我们获得充实感的事情。</p><p>一些我们想做的事。</p><p>一些我们可以不断取得进步的事（而不是日复一日地被困在同样的机械任务中）。</p><p>一些我们可以熟练掌握，以至于能对我们的主要资源（时间、金钱和选择）拥有更多掌控权的事。</p><p>这里会冒出几个问题：</p><ol><li>每个人都想成为创作者，但没人愿意承认这是一门生意，正因如此，你必须学习经营一家企业所需的所有技能（抄送：<a href="https://theone-personbusiness.com/" target="_blank" rel="noreferrer">一人企业</a>）。</li><li>人们以为这很简单，只需发布“真实”的内容，而不必在说服、营销或销售上花任何心思。人们躲在“真实性”这个词——很多人似乎并不理解这个词——背后，这样他们就不必去提升自己在写作、视频、设计等方面的沟通能力。</li><li>当他们最终发现如果不依赖算法，社交媒体的增长其实相对简单时，他们却不知道如何将建立起来的受众变现。</li></ol><p>结果呢？</p><p>100%的人开始了。</p><p>其中1%的人坚持了下来，因为他们的受众在增长。</p><p>这1%中的1%最终完全掌控了自己的收入。</p><p>大多数人放弃是因为他们缺乏解决自身问题的能力。如果他们没有增长，他们会怪罪“触达率”和“算法”，而不是怪自己的内容质量，以及靠人工努力让内容被分享的能力。</p><p>然后，当他们获得增长时，他们会抱怨自我提升或精神探索之类的细分领域“不赚钱”，而不是去测试各种营销角度直到它们<em>变得</em>赚钱。</p><p>（兄弟，没人想“解锁他们的潜力”。去瞄准人们生活中的实际问题吧。）</p><p>那些都不是真的，你只是还算不上一个创业者。你没法戳穿自己的扯淡（bullsh*t），没法去学习解决该问题的技能，也没法坚持这个过程，直到你获得自己想要的成功。</p><p>“技能问题”（skill issue）这个梗是个福音，因为在一个人们整天哀叹抱怨生活不公的世界里，它揭示了一个事实：只要有足够的技能和练习，任何问题都可以被解决。</p><p>我们来深入探讨一下。</p><p>过去我们已经多次讨论过如何实现增长，所以我们将把重点放在人们在变现时常犯的错误上。</p><p>创作者变现有3个阶段。</p><p>大多数人不知道的是，他们可以直接跳到第三阶段。</p><p>在这封信的最后，我将详细说明如果是我，我会先学习什么技能、打造什么产品，以及我会采取哪些具体步骤，来跳过99%的新手创作者都要经历的痛苦。</p><h3 id="阶段-1-把这个头衔看得太重的-内容创作者" tabindex="-1">阶段 1) 把这个头衔看得太重的“内容创作者” <a class="header-anchor" href="#阶段-1-把这个头衔看得太重的-内容创作者" aria-label="Permalink to &quot;阶段 1) 把这个头衔看得太重的“内容创作者”&quot;">​</a></h3><p>我很感激我当初学习所处的商业环境。</p><p>我没读过商业书籍。我在大学商科课上也没认真听讲。商业作为一个概念对我来说从来都没有什么实际意义。</p><p>大多数人会立刻将其斥为“骗局”（或者如果他们还没进入在线商业领域，至少也会对此极度怀疑）的地方，却是我学到几乎所有商业知识的地方。</p><p>我买过关于销售炼金术和靠自由职业获得自由的粗制滥造的电子书。我买过关于如何启动一家六位数收入的广告代运营公司的课程。我买过电商品牌建设课程。我还买过Twitter精通课程。</p><p>这大概是在2017到2018年，当时市场的成熟度还相当低。现在这些知识几乎随处可见。</p><p>有趣的是，我并没有立刻看到结果……很疯狂，我知道。经历了几年的失败后，我的认知才扩展到足以理解所有这些教导。但当一切都豁然开朗时，事情就开始起飞了。</p><p>我最近发现，大多数创作者并没有经历过同样的阶段。</p><p>我不知道现在人们都在教些什么（我根本没去关注），但据说有大量创作者认为仅仅建立受众才是他们成功的关键。</p><p>于是，他们不惜一切代价去建立受众。他们追随热点，迎合算法，不知不觉中，他们拥有了庞大的受众，却没有任何变现知识。</p><p>结果就是，他们依然对作为创作者的潜力一无所知。</p><p>新手的变现方式是：</p><ul><li>赞助</li><li>联盟分销</li><li>平台收益</li></ul><p>除非你拥有<em>庞大且死忠的粉丝群</em>，否则这些方式几乎总是失败的。如果你是一个粉丝数不足10万的账号，就别指望能赚到什么可观的收入了。</p><p>我对处于这个阶段的人的问题是：</p><p>你是否明白，你完全可以自己去打造一个赞助或联盟分销产品的替代版本，然后拿走100%的利润？</p><p>如果你做不到，你也可以围绕赞助和联盟分销打造一个能盈利的产品，然后把它移到后端去赚更多的钱？</p><p>举个例子，如果你是我开发的第二大脑软件Kortex的联盟分销商——你<em>可以</em>完全围绕这款软件建立受众，然后为<strong>我们</strong>赚很多钱。</p><p>或者，你可以打造一款数字产品，比如一门写作课，拿走所有的利润，并把Kortex作为你用来写作的软件进行推广，从而在后端带来持续的联盟分销收入。</p><p>你不需要有经验才能打造产品。我不需要拥有神经科学博士学位，也能打造并发布一款日程规划手册。我只需在亚马逊上买几本规划手册，把其中最有效的部分提炼出来，在Notion里创建我自己的模板，然后卖掉它，拿到成果，<em>这</em>就是我建立信誉的方式。</p><h3 id="阶段-2-在不知不觉中把自己卷入第二份朝九晚五的工作" tabindex="-1">阶段 2) 在不知不觉中把自己卷入第二份朝九晚五的工作 <a class="header-anchor" href="#阶段-2-在不知不觉中把自己卷入第二份朝九晚五的工作" aria-label="Permalink to &quot;阶段 2) 在不知不觉中把自己卷入第二份朝九晚五的工作&quot;">​</a></h3><p>很多人跳过了第一阶段（谢天谢地），因为他们碰巧遇到了教授服务型模式的人，比如自由职业、教练辅导或代运营机构（agency）。</p><p>他们经常听到的承诺是：</p><ul><li>只需2到3个每月付给你2000美元以上的客户，你就能替代现有的收入。</li><li>不需要拥有庞大的粉丝基础，你就能把自己的技能变现。</li><li>你所要做的就是学习一项技能，做免费工作来建立作品集，然后开始联系潜在客户。</li></ul><p>这些都是事实，我也偶尔会教授并推荐这个选项，但新手往往会对这种商业模式的现实感到失望。</p><p>你没意识到这需要多么庞大的开发量，所以你发了20条私信（冷启动开发）就觉得今天可以收工了。就算你发了更多，其中90%都会被无视，5%的人回复让你别来烦人，4%的人只是光看不买的观望者，剩下1%的人找你买了单，结果对你的工作感到失望并要求退款（而退还你好不容易赚到的头几千美元一点都不好玩）。</p><p>当然，对大多数从零开始的人来说这是最坏的情况，而且随着你的练习，你会对这个过程越来越得心应手，但在3个月后，我能理解为什么你觉得在线商业是个骗局，以及为什么你宁愿滚回上一份你讨厌的工作。正如大多数与新手相关的事情一样：这是技能问题。</p><p>我已经意识到，大多数阅读我内容的人还没有准备好为经营一家服务型企业付出所需的投入。</p><p>许多来找我的人处境窘迫，他们必须在3个月内赚到钱，否则生活就会崩溃。我现在就告诉你：想都别想创业。去找一份更好的工作吧，让你能有一些清晰的头脑，以符合道德的方式去建立事业。</p><p>如果你唯一的目标是不择手段地赚钱，你会失败的。你会滥用获客策略（发送垃圾信息），签下几个客户，却无法交付成果，如果你在社交媒体上这么干，还会损害你最初试图建立的声誉。</p><p>你的思维被压力挤压得如此狭隘，以至于你只会选择性地听网上的人在说什么。他们给了你所需要的一切，但你只听取并执行那些快速简单的部分，那你当然会失败。</p><p>其他来找我的人处境相对较好，但我仍然不向大多数人推荐这条变现路径。</p><p>大多数人开始做自由职业或教练是因为他们对某种技能充满热情，但当他们意识到自己并不单纯是对这项技能充满热情，而是对运用这项技能去打造<em>他们</em>想要的东西的能力充满热情时，对这项技能本身的热情就会迅速消退。</p><p>为客户做项目会让你觉得毫无意义，因为你仍然是被分配任务。你没法选择、创造并迭代你自己布置给自己的项目。你的心思依然被困在别人的梦想里，而不是你自己的梦想。</p><p>请记住，我讨论的对象是目标保持“一人企业”形态并完全掌控自己时间的创作者。经营代运营机构没问题，但这几乎需要耗费你100%的精力，直到它能像一台上好油的机器一样顺畅运转，而大多数人并不具备做到这一点的管理技能。</p><p>成为自由职业者或教练是个不错的选择，但它与你刚刚离开的那份工作有几个相似之处。</p><p>首先，通过服务型业务变现是学习赚更多钱所需技能（营销、销售、受众建立、报价制定、交付、运营、内容写作、漏斗等）的极好方式。就像一份工作会教你如何将大学里学到的技能应用到现实世界中一样，这是积极的一面。</p><p>其次，一旦你有了4到6个以上的客户，你的收入就触顶了，你的时间也受限了，就像你打工时一样。</p><p>更进一步说，当初别人告诉你为了拿下客户必须深耕细分领域（niche down），所以现在的你：</p><ul><li>陷入了一个很难转型走出来的细分领域。</li><li>要完成占据了你大半天时间的客户工作。</li><li>如果想生存下去就得去做客户开发（因为客户随时可能离开，让你每个月损失几千美元，非常不稳定）。</li><li>必须努力保持头脑清醒，想出内容创意，以便在你该脱离客户工作时，能有可以作为杠杆利用的受众，但这在你的脑海中排在了最后，而它本该排在第一位。</li></ul><p>你的唯一选择就是涨价、开始雇人，或者近乎从头开始做产品化。我宁愿你不去经历那种痛苦，因为在当今的数字化环境里，你完全没必要这么做。我们已经不再生活在2016年的ClickFunnels时代了，那时候社交媒体上只有巨头网红。小型创作者现在有了机会，因为这个行业已经进化了。</p><h3 id="阶段-3-完全掌控你的收入" tabindex="-1">阶段 3) 完全掌控你的收入 <a class="header-anchor" href="#阶段-3-完全掌控你的收入" aria-label="Permalink to &quot;阶段 3) 完全掌控你的收入&quot;">​</a></h3><p>大多数人是从第二阶段——客户工作——开始的，因为那是目前在线商业的主流范式。</p><p>如前所述，客户工作本身并没有错。它非常适合某些人。但它并不像大多数人鼓吹的那样适合新手。不过，对于那些和我有着相似目标的人——完全掌控我的工作量、我的收入以及我的确切工作内容——还有一条不同的路。</p><ul><li>社群</li><li>课程</li><li>训练营（Cohorts）</li><li>电子书</li><li>其他能在你睡觉时帮你卖钱的数字产品</li></ul><p>很多人对这些东西很反感。</p><p>出于某种原因，他们认为客户工作更可行。“大多数人都这么做，所以我也应该这么做。”他们一生都在学习并为他人工作，因此他们的思维很难理解如何通过为他人做更少的工作来赚取更多的钱。</p><p>为什么我认为这种变现方式比大多数方式更好？</p><p><strong>1) 大多数人宁愿自己学东西，也不愿花钱让别人代劳。高水平的企业家总是为自己和团队购买信息。</strong></p><p>任何想要把事情做完的人，自己先学会这项技能，然后再根据意愿雇人，可能受益会更大。</p><p><strong>2) 在我教过和合作过的人中，99%都不想和超级富豪共事。他们只想和自己喜欢的人一起做自己喜欢的事。</strong></p><p>既然如此，你最好不要把时间浪费在试图向付不起高价的人收取高昂费用上。</p><p>和富人合作是个极好的建议。这非常有效。但我根本不关心如何与他们合作。我想和那些有趣、并且知道自己注定有更大作为的创作者共事。</p><p><strong>3) 大多数人把销售数字产品作为最终目标，但却先从客户工作开始。</strong></p><p>这听起来很合理……从客户工作开始 &gt; 建立受众 &gt; 将你的服务产品化，并开始逐渐摆脱客户工作。</p><p>人们没有意识到，只要具备足够的技能，你从一开始就可以用数字产品变现。我马上就会教你如何做到，但最后还有一件事。</p><p><strong>我不建议像大多数人尝试的那样，从建立社区开始。</strong></p><p>随着 Skool 变得流行，而且头部创作者都拥有了自己的社区，大多数人忘记了这条建议：“做他们一开始做的事，而不是他们现在做的事。”</p><p>你可能没有足够的营销能力来填满一个社区，以达到你想要的月收入。</p><p>就算你有，你可能也没有时间去维护它或雇佣管理员。</p><p>只要建立一个同期群（cohort），收取更高的费用，取得成果，迭代以获得更好的成果，如果你愿意的话，把它变成一个独立的产品，重复这个过程，并在几年后当你建立起完整的价值阶梯时，将这些产品变成社区的额外奖励。</p><p>我会在另一期 newsletter 中谈论这个。</p><h2 id="我究竟是如何从零开始变现的" tabindex="-1">我究竟是如何从零开始变现的 <a class="header-anchor" href="#我究竟是如何从零开始变现的" aria-label="Permalink to &quot;我究竟是如何从零开始变现的&quot;">​</a></h2><p>这一部分是我新产品 <a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">Mental Monetization</a>（我如何构建、发布并维持产品的销售，而不是靠服务）中的一个奖励模块。</p><p>大多数人都不知道，当我第一次开始销售数字产品时，我只有300个粉丝，但我每月的收入已经达到3000美元左右。</p><p>是的，我也在做网页设计的自由职业，所以赚得比这多一点，但我意识到我不需要在客户工作上耗费太久。</p><p>让我们从心态开始拆解这一切：</p><p>如果我想替代我的工资，假设它是美国平均年薪56,000美元：</p><p>这意味着我每个月必须赚大约4,700美元。</p><p>如果做服务，这意味着你需要几个每月付费1,500到3,000美元的客户……听起来很简单，对吧？</p><p>反之，假设我卖一个150美元的数字产品。</p><p>我必须在一个月内卖出大约31个这样的产品，才能赚到4,700美元。</p><p>也就是大概每天卖1个。</p><p>如果我的落地页转化率是2.5%（这很难，但如果是用内容培养起来的受众，而不是通过付费广告吸引来的陌生人，这是有可能的）……</p><p>这个数字仅用于说明。一切都会有所不同。</p><p>这意味着我需要1240人浏览该落地页，才能在2.5%的转化率（访问落地页后购买的人数比例）下，以150美元的价格完成31笔销售，相当于那个月赚取4,700美元。</p><p>到目前为止跟得上吗？</p><p>更进一步，你需要更多的人观看你的实际内容，才能让他们访问你的落地页。</p><p>当我刚起步时，我有直接回应营销（direct response marketing）的经验，所以我明白这一点。</p><p>我只有300个粉丝……那我怎么可能在一个月内让1240人访问我的落地页呢？</p><p>（在我的情况中，人数还要更多，因为我的产品售价在27美元到97美元之间）。</p><p>这些人肯定不会来自我的受众群体，所以他们必须来自别人的受众群体。</p><p>我有几个选项：</p><p><strong>1) 祈祷我能火</strong></p><p>在某些平台上，发布爆款的短片、视频、长帖或图文轮播是完全可能的。</p><p>很难对此做出计划，所以我不会把希望寄托在这上面，但请确保如果你真的火了，你有一个可以推广的产品，能够把人们引流到你的落地页上。</p><p>当你爆火的时候，就是你的收入出现大幅激增的时候。</p><p>你能做的最糟糕的事情，就是火了之后却没有地方安置这些流量。</p><p><strong>2) 组建智囊团</strong></p><p>我说的不是互赞群。</p><p>我说的是与你在社交媒体上交到的朋友组建群聊。它被称为社交媒体是有原因的。</p><p>你可以通过以下两种方式之一来实现：</p><p>和你喜欢并信任的人建立群聊。这就像和朋友一起在游戏大厅里分享策略。偶尔，你可以请他们帮忙分享你写的内容。</p><p>与人进行一对一交流。通过与朋友分享你遇到的资源和策略来维持友谊。偶尔，请他们分享你写的帖子。别忘了告诉他们，也可以发点东西让你帮忙分享作为回报。</p><p>你要试着和水平相仿的人建立友谊。这意味着如果你是个新手，你不会获得海量的流量，但你能得到一些。</p><p>聊胜于无，每一个让更多人看到你产品的努力都算数。</p><p><strong>3) 结交对的人</strong></p><p>人们把人脉建设搞得太复杂了。</p><p>对我们而言，建立人脉就是交朋友。</p><p>我的第一个产品是一门面向网页设计师的自由职业课程。</p><p>我在 Twitter 上找到了其他2位谈论网页设计与开发的创作者。</p><p>他们俩都有大约 15,000 个粉丝。他们没有“大到”会无视我的地步，但他们仍有足够庞大的受众群体，绝对能让其中的 1240 人在一个月内访问我的落地页。</p><p>通过给他们留下好印象（在他们的帖子下评论混个眼熟，并私信称赞他们的内容），他们愿意帮助我。</p><p>其中一人成为了我产品的分销伙伴，因为他们的受众可以从学习做自由职业中获益。</p><p>另一个人则偶尔分享我的内容，这让我获得了更多的展示次数和浏览量，可以在我推广时把流量引入我的落地页。</p><p>这会带来偶尔的流量大爆发，让我能将其导向我的产品。</p><p>如果我写了一篇围绕产品主题的 Twitter 推文长帖或 Instagram 图文轮播，然后他们去分享，我再去推广我的产品，随着长帖被越来越多的人分享，我不明白你凭什么不能在没有庞大受众的情况下，每个月获得几十万次的展示量。</p><p>如果你的产品和营销做得好——就像我们将在这门课中学到的那样——那几十万次的展示就能转化为几万美金。</p><p><strong>4) 为分享付费</strong></p><p>这算是有点“不可告人”的秘密，但我们稍后会详细讨论。</p><p>简而言之，如果你脑子里觉得花钱买分享是不好的，坦白说，你就是个白痴。</p><p>我见过那种以不这么做来占据道德制高点的人，但他们通常根本不知道自己在说些什么。这是一个大品牌和机构一直在使用的切实可行的营销策略。如果你雇佣了一家社交媒体营销机构（真正有真才实学的），他们就会这么做。</p><p>大多数对品牌在社交媒体上进行付费营销说三道四的人（相比于向平台支付天价费用投放广告），通常说的是花钱让主题账号分享是徒劳的，他们在这一点上是对的，但对于其余部分，他们缺乏对微妙细节的理解。</p><p>这个话题我先说到这，你可以自己好好琢磨琢磨。</p><p><strong>总结) 我是如何仅靠300个粉丝实现月入3000美元的</strong></p><ul><li>我写内容</li><li>我有一个好产品</li><li>我利用杠杆借用别人的受众来获取流量，即让我的内容被分享给他们的受众</li><li>我在与产品主题相关的内容上推广我的产品</li><li>我保持一致性，因为流量每天都在波动，并且在一个月后复盘我的进展</li></ul><p>当你把流量获取和转化放在一个长达一个月的时间跨度来看时，作为一个新手，将几十万次的展示转化为几千美元是完全可行的（而且不需要在客户工作上花费大量时间）。</p><p>这期 newsletter 已经很长了。</p><p>我们还得谈谈最适合从哪种类型的产品开始、如何销售，以及所有其他的事情。</p><p>在接下来的几周里，我将拆解与运营这种极简主义商业模式相关的所有内容。技能、心态、日常惯例、习惯等等。</p><p>我们下周聊。</p><p>– Dan</p><hr><p><a href="/en/letters/the-3-stages-of-monetization-why-most-creators-are-actually-broke">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',148))])}const _=a(c,[["render",h]]);export{k as __pageData,_ as default};
